"""Turns src/planted_backtest.json into docs/planted_backtest.md (detection, naming, size accuracy, lifecycle, false flags)."""
import json, pathlib, pandas as pd
root = pathlib.Path(__file__).resolve().parent.parent
def build():
    r = json.loads((root / "src/planted_backtest.json").read_text()); d = pd.DataFrame(r["scenarios"]); L = ["# Planted-shift backtest (section 28)\n", "Shifts planted in a scratch copy of one lender's data; ground truth never shown to the system. Detection uses the original one-step forecasts.\n", "## Scenarios\n"]
    cols = ["name", "kind", "size", "planted_slice_pp", "planted_pool_pp", "n_slice", "n_pool", "detected_any", "detected_priority", "level", "z", "named_correct_top1", "named_correct_top3", "engine_excess_pp", "excess_err_pp"]
    L.append(d[[c for c in cols if c in d]].round(2).to_markdown(index=False)); big = d[d["size"] == "base"]; half = d[d["size"] == "half"]
    rate = lambda x, c: f"{int(x[c].fillna(False).astype(bool).sum())}/{len(x)}"
    L += ["", "## Summary", "", "| | base size | half size |", "|---|---|---|", f"| detected at all | {rate(big, 'detected_any')} | {rate(half, 'detected_any')} |", f"| detected as a priority investigation | {rate(big, 'detected_priority')} | {rate(half, 'detected_priority')} |"]
    nm = lambda x, c: f"{int(x[c].dropna().astype(bool).sum())}/{int(x[c].notna().sum())}"
    L += [f"| planted slice named (top 1) where a slice exists | {nm(big, 'named_correct_top1')} | {nm(half, 'named_correct_top1')} |", f"| planted slice in the top 3 | {nm(big, 'named_correct_top3')} | {nm(half, 'named_correct_top3')} |"]
    e = d.excess_err_pp.dropna(); L += ["", f"Size accuracy: engine excess minus planted effect, mean absolute error {e.abs().mean():.1f} pp over {len(e)} scenarios (median {e.abs().median():.1f})." if len(e) else "", "", "## Shape classification (driver registry lifecycle)", "", "| shape planted | expected status | status after 2 re-checks | correct |", "|---|---|---|---|"]
    for x in r["lifecycle"]: L.append(f"| {x['name']} | {', '.join(x['expected'])} | {x['status']} | {x.get('ok', False)} |")
    if r.get("diagnostics"):
        L += ["", "## Diagnostic: naming when the profiler looks at the TRUE affected pool", "", "| scenario | planted slice named top 1 | in top 3 | slices flagged | top 3 (dimension, slice, did_pp, z) |", "|---|---|---|---|---|"] + [f"| {x['name']} | {x['top1_correct']} | {x['top3_correct']} | {x['n_flagged']} | {x['top3']} |" for x in r["diagnostics"]]
    ff = pd.DataFrame(r["false_flags"]); L += ["", "## False flags on unmodified data (Jun-Sep 2025, no new seeded events)", "", ff.to_markdown(index=False), "", f"Mean flagged investigations per lender-month: {ff.all_flags.mean():.2f}; priority: {ff.priority_flags.mean():.2f}."]
    L += ["", "## Reading the results", "",
          "- **Detection is power-limited, not broken.** Shifts with a pool-level effect of about 2.7 points or more (agency collapse, policy step at full size) and lender-wide shifts as small as 0.6 points (large pool, so little noise) were detected. Pool-level effects of 0.5-1.0 points on a small slice (weak cohort 0.7, city shock 1.0) were missed. The leading-indicator scan (section 11), which might catch the cohort and city cases, is not part of this harness.",
          "- **Naming fails on a single month of a small pool.** For the agency and policy shifts the profiler flags no slice at all, even when pointed at the true pool: a 10-point effect on about 340 accounts is only about 2.3 sigma, and the false-discovery correction across about 100 candidate slices removes it. The cohort and city cases do put the planted slice in the top 3 when the true pool is searched, but not at top 1 (the complementary slice or the parent state ranks first).",
          "- **The detected sub-pool is often not the true pool,** so the investigator searches the wrong population (agency case: it looked at one product segment of the West pool). Searching at the true pool helps for cohort and city, not for agency and policy.",
          "- **Size accuracy** is poor where naming failed (the engine quantified a wrong slice: about 13-14 points off).",
          "- **Shape classification is sound when the signal is strong** (3 of 3 on a high-power pool) and wrong on the noisy pool (a persistent step was closed as a blip because one month of about 600 accounts is too noisy to confirm persistence).",
          "- **False flags:** the unmodified Jun-Sep 2025 months show about 1.8 flagged and 0.3 priority investigations per lender-month. Some are real (the ongoing West agency attrition and Lender B Autopay shifts are in these months), so this is an upper bound.",
          "", "## Limits of this harness", "", "One planted month (July 2025), one lender and one seed per shift type, five shift types, two sizes. The investigator is the rule-based one (the LLM Detective has not run). Detection uses forecasts made before the planted month. Results are indicative, not statistics.",
          "", "## What section 29 should do with this", "", "1. Let the profiler use a multi-month window (and the registry's persistence) once a shift is first flagged, since a single month cannot name a mid-sized slice.", "2. Investigate at the true pool: when several sub-pools of one parent flag together, profile the parent.", "3. Revisit the slice screening (q = 0.10 across about 100 hypotheses) and consider a two-stage search (dimension first, then value).", "4. Re-tune detection thresholds with this harness extended to more seeds, months and lenders, and add the leading-indicator path to the detection score.", "5. Make the rule-based investigator say plainly when it has no power to name a slice (it currently names whatever is largest)."]
    (root / "docs/planted_backtest.md").write_text("\n".join(L)); return "\n".join(L)
if __name__ == "__main__": print(build())
